using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_relevantly));

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_follows_instructions()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_follows_instructions));

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "Explain what an API is.")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT is not set.");
        var deploymentName = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

        IChatClient evaluatorClient =
            new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint),
                new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deploymentName)
            .AsIChatClient();

        IChatClient chatClient =
            new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint),
                new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deploymentName)
            .AsIChatClient();

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(chatClient);

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: "eval-results",
            evaluators: evaluators,
            chatConfiguration: chatConfiguration,
            evaluatorChatConfiguration: new ChatConfiguration(evaluatorClient));
    }
}

